package dev.pivot.matrix;

import android.content.Context;
import android.graphics.*;
import android.media.ExifInterface;
import android.net.Uri;
import java.io.*;
import java.util.*;

final class ScanImage {
 static Bitmap decode(Context context,Uri uri,int limit)throws IOException{
  if(uri==null)throw new IOException("Missing image");BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;try(InputStream stream=context.getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(stream,null,options);}if(options.outWidth<=0||options.outHeight<=0)throw new IOException("Invalid image");options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>limit)options.inSampleSize*=2;options.inJustDecodeBounds=false;options.inPreferredConfig=Bitmap.Config.ARGB_8888;Bitmap bitmap;try(InputStream stream=context.getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(stream,null,options);}if(bitmap==null)throw new IOException("Image decode failed");int orientation;try(InputStream stream=context.getContentResolver().openInputStream(uri)){orientation=new ExifInterface(stream).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);}catch(IOException e){orientation=ExifInterface.ORIENTATION_NORMAL;}Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(-90);matrix.postScale(-1,1);break;case 8:matrix.setRotate(-90);break;default:return bitmap;}Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(rotated!=bitmap)bitmap.recycle();return rotated;
 }
 static final class Component {
  final Rect box;final int area,seed;
  Component(Rect box,int area,int seed){this.box=box;this.area=area;this.seed=seed;}
 }
 final int width,height;final byte[] ink;final List<Component> components=new ArrayList<>();int removedBrackets;
 ScanImage(Bitmap bitmap){width=bitmap.getWidth();height=bitmap.getHeight();ink=new byte[width*height];int[] pixels=new int[ink.length];bitmap.getPixels(pixels,0,width,0,0,width,height);int[] sums=new int[(width+1)*(height+1)];for(int y=0;y<height;y++){int row=0;for(int x=0;x<width;x++){int color=pixels[y*width+x];int gray=(Color.red(color)*77+Color.green(color)*150+Color.blue(color)*29)>>8;pixels[y*width+x]=gray;row+=gray;sums[(y+1)*(width+1)+x+1]=sums[y*(width+1)+x+1]+row;}}
  int radius=Math.max(12,Math.min(width,height)/24);for(int y=0;y<height;y++)for(int x=0;x<width;x++){int left=Math.max(0,x-radius),right=Math.min(width,x+radius+1),top=Math.max(0,y-radius),bottom=Math.min(height,y+radius+1);int mean=(sums[bottom*(width+1)+right]-sums[top*(width+1)+right]-sums[bottom*(width+1)+left]+sums[top*(width+1)+left])/((right-left)*(bottom-top));if(pixels[y*width+x]<Math.max(45,Math.min(235,mean-13)))ink[y*width+x]=1;}
  collect();removeBrackets();
 }
 private void collect(){boolean[] seen=new boolean[ink.length];int[] queue=new int[ink.length];for(int seed=0;seed<ink.length;seed++){if(ink[seed]==0||seen[seed])continue;int head=0,tail=1;queue[0]=seed;seen[seed]=true;int left=width,right=0,top=height,bottom=0;while(head<tail){int at=queue[head++],x=at%width,y=at/width;left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=x+dx,yy=y+dy;if(xx<0||xx>=width||yy<0||yy>=height)continue;int next=yy*width+xx;if(ink[next]!=0&&!seen[next]){seen[next]=true;queue[tail++]=next;}}}if(tail>=Math.max(3,ink.length/500000))components.add(new Component(new Rect(left,top,right+1,bottom+1),tail,seed));}}
 private void removeBrackets(){if(components.size()<2)return;int min=width,max=0;List<Integer> heights=new ArrayList<>();for(Component component:components){min=Math.min(min,component.box.left);max=Math.max(max,component.box.right);}for(Component component:components)if(component.box.left>min+(max-min)*.12&&component.box.right<max-(max-min)*.12&&component.box.height()>6)heights.add(component.box.height());if(heights.isEmpty())for(Component c:components)if(c.box.height()>6)heights.add(c.box.height());if(heights.isEmpty())return;Collections.sort(heights);float median=heights.get(heights.size()/2);Iterator<Component> iterator=components.iterator();while(iterator.hasNext()){Component c=iterator.next();boolean left=c.box.left<=min+(max-min)*.12,right=c.box.right>=max-(max-min)*.12;if((left||right)&&c.box.height()>=median*1.5&&bracketShape(c,left)){erase(c);iterator.remove();removedBrackets++;}}}
 boolean bracketShape(Component c,boolean left){Rect box=c.box;if(box.height()<24||box.height()<box.width()*1.8)return false;int band=Math.max(2,box.height()/7);int top=span(box,box.top,box.top+band),bottom=span(box,box.bottom-band,box.bottom),middle=span(box,box.centerY()-band/2,box.centerY()+band/2);if(top<Math.max(5,middle*1.6)||bottom<Math.max(5,middle*1.6))return false;long sx=0,count=0;for(int y=box.top+band;y<box.bottom-band;y++)for(int x=box.left;x<box.right;x++)if(ink[y*width+x]!=0){sx+=x;count++;}if(count==0)return false;float center=(float)sx/count;return left?center<box.left+box.width()*.36:center>box.left+box.width()*.64;}
 private int span(Rect box,int top,int bottom){int left=box.right,right=box.left;for(int y=Math.max(box.top,top);y<Math.min(box.bottom,bottom);y++)for(int x=box.left;x<box.right;x++)if(ink[y*width+x]!=0){left=Math.min(left,x);right=Math.max(right,x);}return Math.max(0,right-left+1);}
 private void erase(Component c){boolean[] visited=new boolean[ink.length];int[] queue=new int[c.area+1];int head=0,tail=1;queue[0]=c.seed;visited[c.seed]=true;while(head<tail){int at=queue[head++],x=at%width,y=at/width;ink[at]=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=x+dx,yy=y+dy;if(xx<0||xx>=width||yy<0||yy>=height)continue;int next=yy*width+xx;if(ink[next]!=0&&!visited[next]){visited[next]=true;queue[tail++]=next;}}}}
 Bitmap cleaned(Bitmap original,boolean contrast){Bitmap result=original.copy(Bitmap.Config.ARGB_8888,true);int[] pixels=new int[ink.length];original.getPixels(pixels,0,width,0,0,width,height);for(int i=0;i<pixels.length;i++)if(contrast)pixels[i]=ink[i]!=0?Color.BLACK:Color.WHITE;else if(ink[i]==0){int color=pixels[i];if(((Color.red(color)*77+Color.green(color)*150+Color.blue(color)*29)>>8)<100)pixels[i]=Color.WHITE;}result.setPixels(pixels,0,width,0,0,width,height);return result;}
}
